import{_ as t,o as a,c as e,a3 as i}from"./chunks/framework.uTHcANy5.js";const k=JSON.parse('{"title":"Packing","description":"","frontmatter":{},"headers":[],"relativePath":"tools/pack.md","filePath":"tools/pack.md"}'),o={name:"tools/pack.md"};function d(n,s,c,h,l,p){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="packing" tabindex="-1">Packing <a class="header-anchor" href="#packing" aria-label="Permalink to &quot;Packing&quot;">​</a></h1><p><code>mosaic pack</code> turns anything Mosaic reads into a <code>.tsr</code> archive, or into an editable source document. It decides what the input is by its extension, and what to write by the output&#39;s:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">inpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [output.tsr </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> output.mosaic.json]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [flags]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Input</th><th>Packed as</th><th>Flags</th></tr></thead><tbody><tr><td><code>.json</code>, <code>.mosaic.json</code></td><td>A Mosaic source document, packed as written</td><td></td></tr><tr><td><code>.gltf</code>, <code>.glb</code>, or an <code>http(s)</code> URL to one</td><td>A glTF model, converted. See <a href="/mosaic/dist/docs/tools/gltf">Importing glTF</a></td><td><code>--stable-ids</code></td></tr><tr><td><code>.ifc</code></td><td>An IFC4 or IFC2X3 model, converted. See <a href="/mosaic/dist/docs/tools/ifc">Importing IFC</a></td><td><code>--center</code>, <code>--no-geometry</code>, <code>--seed=&lt;text&gt;</code></td></tr><tr><td><code>.svg</code></td><td>A drawing, carried whole as one node. See <a href="/mosaic/dist/docs/tools/svg">SVG</a></td><td></td></tr></tbody></table><p>The output&#39;s extension says what to write:</p><table tabindex="0"><thead><tr><th>Output</th><th>Writes</th></tr></thead><tbody><tr><td>left out, or <code>*.tsr</code></td><td>A <code>.tsr</code> archive. Left out, it goes next to the input with the same name: <code>tower.ifc</code> becomes <code>tower.tsr</code>. A model packed from a URL goes to the working directory</td></tr><tr><td><code>*.mosaic.json</code></td><td>The converted model as an editable source document, instead of an archive. glTF and IFC only</td></tr></tbody></table><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-1" id="tab-1-1" checked><label data-title="source document" for="tab-1-1">source document</label><input type="radio" name="group-1" id="tab-1-2"><label data-title="glTF" for="tab-1-2">glTF</label><input type="radio" name="group-1" id="tab-1-3"><label data-title="IFC" for="tab-1-3">IFC</label><input type="radio" name="group-1" id="tab-1-4"><label data-title="edit, then pack" for="tab-1-4">edit, then pack</label><input type="radio" name="group-1" id="tab-1-5"><label data-title="SVG" for="tab-1-5">SVG</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> house-v1.mosaic.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # -&gt; house-v1.tsr</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DamagedHelmet.glb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stable-ids</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # -&gt; DamagedHelmet.tsr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://tomvandig.github.io/mosaic/dist/docs/models/DamagedHelmet.glb</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tower.ifc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --center</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # -&gt; tower.tsr</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tower.ifc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tower.mosaic.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # convert to a source document</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># … edit tower.mosaic.json …</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tower.mosaic.json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # -&gt; tower.tsr</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drawing.svg</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # -&gt; drawing.tsr</span></span></code></pre></div></div></div><p>Every archive <code>pack</code> writes stands alone: the component schemas are inlined, and so are a glTF&#39;s buffers.</p><p>To edit a converted model before packing it, name the output <code>.mosaic.json</code>, change the JSON, then <code>mosaic pack</code> that. An SVG has no source document, since it is carried whole rather than taken apart, and a source document can only be packed to an archive.</p><h2 id="source-documents" tabindex="-1">Source documents <a class="header-anchor" href="#source-documents" aria-label="Permalink to &quot;Source documents&quot;">​</a></h2><p>A Mosaic dataset can be authored as one JSON document, the index plus the component rows. Packing resolves each <code>componentTables[].schema</code> reference (a path relative to the source document) into the schema document itself, writes one <code>&lt;type&gt;.ndjson</code> file per component table, and puts them alongside <code>index.json</code> in the archive.</p><p>The source-document format is described in <a href="https://github.com/tomvandig/mosaic/blob/main/sdk/ts/test-data/README.md" target="_blank" rel="noreferrer"><code>sdk/ts/test-data/README.md</code></a>, and the packing itself lives in the TypeScript SDK (<code>buildMosaicFile</code>, <code>packMosaicSource</code>, <code>packMosaicSourceFile</code>), which the CLI depends on. The same behaviour is available to any consumer of the SDK.</p>`,12)])])}const g=t(o,[["render",d]]);export{k as __pageData,g as default};
